'use client';

import { useTheme } from 'next-themes';

import DarkVeil from './dark-veil';

type HeroDarkVeilProps = { reducedMotion: boolean };

export function HeroDarkVeil({ reducedMotion }: HeroDarkVeilProps) {
  const { resolvedTheme } = useTheme();
  const lightMode = resolvedTheme !== 'dark';

  if (reducedMotion) return <div className="hero-dark-veil hero-dark-veil-static" aria-hidden="true" />;

  return (
    <div className="hero-dark-veil" aria-hidden="true">
      <DarkVeil
        lightMode={lightMode}
        speed={0.9}
        noiseIntensity={0.035}
        scanlineIntensity={0.045}
        scanlineFrequency={0.12}
        warpAmount={0.12}
        resolutionScale={0.7}
      />
    </div>
  );
}
